import React, { useState } from 'react';
import { GoogleGenAI, Type } from "@google/genai";
import { DietType, Goal, DietPlan } from '../types';
import { saveToSheet } from '../services/api';
import { WHATSAPP_LINK } from '../constants';

const DietPlanner: React.FC = () => {
  const [loading, setLoading] = useState(false);
  const [generatedPlan, setGeneratedPlan] = useState<DietPlan | null>(null);
  const [formData, setFormData] = useState({
    name: '',
    phone: '',
    weight: '',
    height: '',
    goal: Goal.WEIGHT_LOSS,
    type: DietType.VEG
  });

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
    setFormData({ ...formData, [e.target.name]: e.target.value });
  };

  const generateDietPlanWithAI = async (user: typeof formData): Promise<DietPlan | null> => {
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

      const prompt = `
        Create a customized daily diet plan for an Indian client based on the following details:
        - Name: ${user.name}
        - Current Weight: ${user.weight} kg
        - Height: ${user.height} cm
        - Goal: ${user.goal}
        - Dietary Preference: ${user.type}

        The plan must include:
        1. A morning detox drink.
        2. A nutritious breakfast.
        3. A balanced lunch.
        4. A healthy evening snack.
        5. A light dinner.
        6. Recommended natural or ayurvedic supplements.

        Constraints:
        - Use Indian food examples (e.g., Poha, Dal, Roti, Paneer).
        - Keep descriptions short and actionable (under 10 words).
        - Output strictly valid JSON matching the schema.
      `;

      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: prompt,
        config: {
          responseMimeType: 'application/json',
          responseSchema: {
            type: Type.OBJECT,
            properties: {
              morningDrink: { type: Type.STRING, description: "Morning drink suggestion" },
              breakfast: { type: Type.STRING, description: "Breakfast suggestion" },
              lunch: { type: Type.STRING, description: "Lunch suggestion" },
              snack: { type: Type.STRING, description: "Snack suggestion" },
              dinner: { type: Type.STRING, description: "Dinner suggestion" },
              supplements: { type: Type.STRING, description: "Supplement suggestions" },
            },
            required: ['morningDrink', 'breakfast', 'lunch', 'snack', 'dinner', 'supplements'],
          }
        }
      });

      if (response.text) {
        return JSON.parse(response.text) as DietPlan;
      }
      return null;

    } catch (error) {
      console.error("AI Generation failed:", error);
      return null;
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    setGeneratedPlan(null);

    // 1. Generate Plan with AI
    const plan = await generateDietPlanWithAI(formData);

    // 2. Save to SheetDB (Non-blocking for UI, but after generation to ensure validity)
    saveToSheet({
      date: new Date().toLocaleDateString(),
      ...formData
    }).catch(err => console.error("SheetDB save error", err));

    // 3. Show Result
    if (plan) {
      setGeneratedPlan(plan);
    } else {
      alert("Unable to generate plan at the moment. Please try again or check your connection.");
    }

    setLoading(false);
  };

  return (
    <section id="planner" className="py-20 bg-slate-900 relative overflow-hidden">
      {/* Decorative blobs */}
      <div className="absolute top-0 left-0 w-64 h-64 bg-emerald-500/20 rounded-full blur-3xl -translate-x-1/2 -translate-y-1/2"></div>
      <div className="absolute bottom-0 right-0 w-80 h-80 bg-blue-500/20 rounded-full blur-3xl translate-x-1/2 translate-y-1/2"></div>

      <div className="container mx-auto px-4 relative z-10">
        <div className="text-center mb-12">
          <h2 className="text-3xl md:text-5xl font-extrabold text-white mb-4">AI Diet Planner</h2>
          <p className="text-gray-400">Get a personalized nutrition roadmap powered by Gemini AI.</p>
        </div>

        <div className="grid md:grid-cols-2 gap-12 items-start">
          {/* Form */}
          <div className="glass-dark p-8 rounded-3xl shadow-2xl">
            <form onSubmit={handleSubmit} className="space-y-6">
              <div className="grid md:grid-cols-2 gap-6">
                <div>
                    <label className="block mb-2 text-sm font-medium text-gray-300">Full Name</label>
                    <input type="text" name="name" required className="bg-slate-800 border border-slate-700 text-white text-sm rounded-xl focus:ring-emerald-500 focus:border-emerald-500 block w-full p-3" placeholder="John Doe" onChange={handleInputChange} />
                </div>
                <div>
                    <label className="block mb-2 text-sm font-medium text-gray-300">Phone</label>
                    <input type="tel" name="phone" required className="bg-slate-800 border border-slate-700 text-white text-sm rounded-xl focus:ring-emerald-500 focus:border-emerald-500 block w-full p-3" placeholder="+91..." onChange={handleInputChange} />
                </div>
              </div>

              <div className="grid md:grid-cols-2 gap-6">
                 <div>
                    <label className="block mb-2 text-sm font-medium text-gray-300">Weight (kg)</label>
                    <input type="number" name="weight" required className="bg-slate-800 border border-slate-700 text-white text-sm rounded-xl focus:ring-emerald-500 focus:border-emerald-500 block w-full p-3" placeholder="70" onChange={handleInputChange} />
                </div>
                <div>
                    <label className="block mb-2 text-sm font-medium text-gray-300">Height (cm)</label>
                    <input type="number" name="height" required className="bg-slate-800 border border-slate-700 text-white text-sm rounded-xl focus:ring-emerald-500 focus:border-emerald-500 block w-full p-3" placeholder="175" onChange={handleInputChange} />
                </div>
              </div>

              <div className="grid md:grid-cols-2 gap-6">
                <div>
                    <label className="block mb-2 text-sm font-medium text-gray-300">Goal</label>
                    <select name="goal" className="bg-slate-800 border border-slate-700 text-white text-sm rounded-xl focus:ring-emerald-500 focus:border-emerald-500 block w-full p-3" onChange={handleInputChange}>
                        {Object.values(Goal).map(g => <option key={g} value={g}>{g}</option>)}
                    </select>
                </div>
                <div>
                    <label className="block mb-2 text-sm font-medium text-gray-300">Diet Type</label>
                    <select name="type" className="bg-slate-800 border border-slate-700 text-white text-sm rounded-xl focus:ring-emerald-500 focus:border-emerald-500 block w-full p-3" onChange={handleInputChange}>
                        {Object.values(DietType).map(t => <option key={t} value={t}>{t}</option>)}
                    </select>
                </div>
              </div>

              <button type="submit" disabled={loading} className="w-full text-slate-900 bg-emerald-400 hover:bg-emerald-500 focus:ring-4 focus:outline-none focus:ring-emerald-300 font-bold rounded-xl text-lg px-5 py-4 text-center transition-all disabled:opacity-50 disabled:cursor-not-allowed">
                {loading ? <i className="fas fa-spinner fa-spin mr-2"></i> : <i className="fas fa-sparkles mr-2"></i>}
                {loading ? 'Consulting AI...' : 'Generate Plan'}
              </button>
            </form>
          </div>

          {/* Result Area */}
          <div className="relative">
             {!generatedPlan ? (
                 <div className="flex flex-col items-center justify-center h-full min-h-[400px] glass-dark rounded-3xl p-8 text-gray-400 border-dashed border-2 border-gray-700 transition-all">
                     <i className={`fas fa-utensils text-6xl mb-4 ${loading ? 'animate-bounce text-emerald-500' : 'opacity-30'}`}></i>
                     <p className={loading ? 'text-emerald-400 animate-pulse' : ''}>
                        {loading ? 'Analyzing your body metrics...' : 'Your custom plan will appear here'}
                     </p>
                 </div>
             ) : (
                 <div className="glass-dark rounded-3xl p-8 border border-emerald-500/30 animate-fade-in-up">
                    <div className="flex justify-between items-center mb-6">
                        <h3 className="text-2xl font-bold text-emerald-400">Your AI Plan</h3>
                        <span className="bg-emerald-900 text-emerald-300 text-xs font-medium px-2.5 py-0.5 rounded-full">{formData.goal}</span>
                    </div>

                    <ul className="space-y-4">
                        <li className="flex items-start">
                            <div className="flex-shrink-0 w-10 h-10 rounded-full bg-slate-800 flex items-center justify-center text-yellow-400 mr-4 border border-slate-700">
                                <i className="fas fa-sun"></i>
                            </div>
                            <div>
                                <h4 className="text-white font-semibold">Morning Drink</h4>
                                <p className="text-gray-400 text-sm">{generatedPlan.morningDrink}</p>
                            </div>
                        </li>
                        <li className="flex items-start">
                            <div className="flex-shrink-0 w-10 h-10 rounded-full bg-slate-800 flex items-center justify-center text-orange-400 mr-4 border border-slate-700">
                                <i className="fas fa-coffee"></i>
                            </div>
                            <div>
                                <h4 className="text-white font-semibold">Breakfast</h4>
                                <p className="text-gray-400 text-sm">{generatedPlan.breakfast}</p>
                            </div>
                        </li>
                        <li className="flex items-start">
                            <div className="flex-shrink-0 w-10 h-10 rounded-full bg-slate-800 flex items-center justify-center text-green-400 mr-4 border border-slate-700">
                                <i className="fas fa-leaf"></i>
                            </div>
                            <div>
                                <h4 className="text-white font-semibold">Lunch</h4>
                                <p className="text-gray-400 text-sm">{generatedPlan.lunch}</p>
                            </div>
                        </li>
                        <li className="flex items-start">
                            <div className="flex-shrink-0 w-10 h-10 rounded-full bg-slate-800 flex items-center justify-center text-teal-400 mr-4 border border-slate-700">
                                <i className="fas fa-cookie-bite"></i>
                            </div>
                            <div>
                                <h4 className="text-white font-semibold">Snack</h4>
                                <p className="text-gray-400 text-sm">{generatedPlan.snack}</p>
                            </div>
                        </li>
                        <li className="flex items-start">
                            <div className="flex-shrink-0 w-10 h-10 rounded-full bg-slate-800 flex items-center justify-center text-indigo-400 mr-4 border border-slate-700">
                                <i className="fas fa-moon"></i>
                            </div>
                            <div>
                                <h4 className="text-white font-semibold">Dinner</h4>
                                <p className="text-gray-400 text-sm">{generatedPlan.dinner}</p>
                            </div>
                        </li>
                         <li className="flex items-start">
                            <div className="flex-shrink-0 w-10 h-10 rounded-full bg-slate-800 flex items-center justify-center text-purple-400 mr-4 border border-slate-700">
                                <i className="fas fa-pills"></i>
                            </div>
                            <div>
                                <h4 className="text-white font-semibold">Supplements</h4>
                                <p className="text-gray-400 text-sm">{generatedPlan.supplements}</p>
                            </div>
                        </li>
                    </ul>

                    <div className="mt-8 pt-6 border-t border-gray-700">
                        <p className="text-gray-300 text-center mb-4 text-sm">Want to refine this plan?</p>
                        <a href={WHATSAPP_LINK} target="_blank" rel="noreferrer" className="flex items-center justify-center w-full text-white bg-green-600 hover:bg-green-700 font-bold rounded-xl text-md px-5 py-3 transition-colors">
                            <i className="fab fa-whatsapp mr-2 text-xl"></i>
                            Chat with Coach Saroj
                        </a>
                    </div>
                 </div>
             )}
          </div>
        </div>
      </div>
    </section>
  );
};

export default DietPlanner;
